DROP TABLE IF EXISTS `appointmentList`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `appointmentList` (
  `appointment_id` int NOT NULL AUTO_INCREMENT,
  `appointment_datetime` datetime DEFAULT NULL,
  `appointment_date` datetime DEFAULT NULL,
  `name` varchar(255) DEFAULT NULL,
  `specialty` varchar(50) DEFAULT NULL,
  `gender` tinyint DEFAULT NULL,
  `age` int DEFAULT NULL,
  `under_12_years_old` tinyint DEFAULT NULL,
  `over_60_years_old` tinyint DEFAULT NULL,
  `patient_needs_companion` tinyint DEFAULT NULL,
  `disability` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `no_show` tinyint DEFAULT NULL,
  `icd` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL,
  `entry_service_date` date DEFAULT NULL,
  PRIMARY KEY (`appointment_id`)
) ENGINE=InnoDB AUTO_INCREMENT=248696 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
